public class Pair<T, V> {
    private T data1;
    private V data2;

    public void setValue(T dt1, V dt2) {
        data1 = dt1;
        data2 = dt2;
    }

    public T getT1Value() { return data1; }
    public V getT2Value() { return data2; }
}

public class PairDemo {
    public static void main(String[] args) {
        Pair<Integer, String>  mixData = new Pair<>();
        Pair<Integer, Integer> iData   = new Pair<>();

        mixData.setValue(1, "One");
        iData.setValue(7, 25);

        int    mdType1 = mixData.getT1Value();
        String mdType2 = mixData.getT2Value();
        int    idType1 = iData.getT1Value();
        int    idType2 = iData.getT2Value();

        System.out.println("First pair: "  + mdType1 + " and " + mdType2);
        System.out.println("Second pair: " + idType1 + " and " + idType2);
    }
}
